import pandas as pd

CONTRADICTS = "Contradicts"


def transform(row):
    commitment = row["public_commitment"]
    if commitment is None or bool(pd.isna(commitment)):
        # The join matched no commitment for this client, so there is nothing to
        # contradict. Code decides this, not the model.
        return {**row, "contradicts_commitment": False}
    alignment = row["alignment"]
    if alignment is None or bool(pd.isna(alignment)):
        raise StepRefused(
            f"filing {row['filing_id']} carries a public commitment but no judgment "
            f"on it, so whether it contradicts that commitment cannot be decided"
        )
    return {**row, "contradicts_commitment": str(alignment) == CONTRADICTS}

import html as _html
import pathlib

import pandas as pd

# The page's markup, in the stage that writes it. A publish stage emits a document, so
# its markup is part of what the stage IS — a reader reviewing this step reads it here
# rather than chasing a file the workflow does not carry.
DOCUMENT = """\
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Tutorial Lobbying Say-versus-Do</title>
<style>
  body { font-family: -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
         margin: 2rem auto; max-width: 1180px; padding: 0 1rem; line-height: 1.45; }
  h1 { font-size: 1.45rem; margin-bottom: .2rem; }
  p { margin: .5rem 0; }
  .sub, .note, .muted, .src { font-size: .85rem;
        color: color-mix(in srgb, currentColor 60%, transparent); }
  .note, .why { border-left: 3px solid color-mix(in srgb, currentColor 30%, transparent);
        padding: .1rem 0 .1rem .8rem; margin: 1rem 0; }
  .why { font-size: .9rem; max-width: 62ch; }
  table { border-collapse: collapse; width: 100%; font-size: .88rem; margin-top: 1.4rem; }
  th, td { text-align: left; padding: .5rem .6rem; vertical-align: top;
           border-bottom: 1px solid color-mix(in srgb, currentColor 15%, transparent); }
  th { font-size: .7rem; text-transform: uppercase; letter-spacing: .05em;
       border-bottom-width: 2px; }
  td.num { font-variant-numeric: tabular-nums; font-weight: 600; white-space: nowrap; }
  tr.flagged td:first-child { border-left: 3px solid currentColor; }
  .pill { border: 1px solid color-mix(in srgb, currentColor 30%, transparent);
          border-radius: 999px; padding: .05rem .5rem; font-size: .78rem;
          white-space: nowrap; }
  .none { color: color-mix(in srgb, currentColor 40%, transparent); font-style: italic; }
  .src { display: block; margin-top: .2rem; }
  .quote { margin: .4rem 0 0; font-size: .82rem; max-width: 44ch; }
  .label { font-weight: 700; text-transform: uppercase; letter-spacing: .04em;
           font-size: .7rem; display: block; }
</style>
</head>
<body>
<h1>Tutorial Say-versus-Do Report</h1>
<p class="sub">[[filing_count]] filings; [[flagged_count]] ask government for the opposite of what their client committed to in public; [[unmatched_count]] have no public commitment on record.</p>
<p class="note">Invented sample data bundled with this tutorial. No row describes a real filing, client, firm or commitment.</p>
<p class="why">Beside each filing sits what the same client said in public, where a commitment was on
record. A filing is marked when it asks government for the opposite of that commitment &mdash; and where
it is marked, both texts are printed together, so the contradiction is on the page rather than only in
the flag. It is a reading aid, not a verdict, and not a finding about the filer.
Every row carries a <em>Show the work</em> link back through each stage that touched it to the input row
it came from. Those links are served by the app that produced this page; in a copy of this file opened
on its own they will not resolve.</p>
<table>
<thead><tr>
<th>Filing</th><th>Client</th><th>Registrant</th><th>Period</th>
<th>Reported spend</th><th>What this filing asks for</th><th>What they said in public</th><th>Why follow up</th>
<th>Show the work</th>
</tr></thead>
<tbody>
[[rows]]</tbody>
</table>
</body>
</html>
"""

ROW = """\
<tr class="[[row_class]]">
<td>[[filing_id]]</td>
<td>[[client]]</td>
<td class="muted">[[registrant]]</td>
<td>[[filing_period]]</td>
<td class="num">[[amount]]</td>
<td>[[specific_issues]]</td>
<td>[[commitment]]</td>
<td>[[followup]]</td>
<td>[[trace]]</td>
</tr>
"""

TRACE = """\
<a href="[[trace_url]]">Lineage</a>
"""

COMMITMENT = """\
[[public_commitment]]<span class="src">[[commitment_source]]</span>
"""

NO_COMMITMENT = """\
<span class="none">No public commitment on record</span>
"""

JUDGMENT = """\
<span class="pill">[[alignment]]</span>
"""

CONTRADICTION = """\
<p class="quote"><span class="label">Said</span>[[said]]</p>
<p class="quote"><span class="label">Lobbied for</span>[[lobbied_for]]</p>
"""

SECTIONS = {
    "document": DOCUMENT, "row": ROW, "trace": TRACE, "commitment": COMMITMENT,
    "no_commitment": NO_COMMITMENT, "judgment": JUDGMENT, "contradiction": CONTRADICTION,
}
TOKEN_OPEN = "[["


# The ordinal a trace URL needs is a position in THIS frame, so the stage it names is
# this step's own input, and the rows are rendered in the order they arrived.
TRACED_INPUT = "flag_contradiction"
NOT_JUDGED = "not judged"
NO_SOURCE = "source not recorded"


def transform(df, output_dir, trace_links):
    sections = SECTIONS
    page = _fill(
        sections["document"],
        filing_count=str(len(df)),
        flagged_count=str(int(df["contradicts_commitment"].sum())),
        unmatched_count=str(int(df["public_commitment"].isna().sum())),
        rows="".join(
            _render_row(sections, row, trace_links, ordinal)
            for ordinal, (_, row) in enumerate(df.iterrows())
        ),
    )
    out_path = pathlib.Path(output_dir) / "tutorial_triage_report.html"
    out_path.write_text(page, encoding="utf-8")
    return pd.DataFrame([{"report_path": str(out_path), "filing_count": len(df)}])


def _render_row(sections, row, trace_links, ordinal):
    return _fill(
        sections["row"],
        row_class="flagged" if bool(row["contradicts_commitment"]) else "",
        filing_id=_escaped(row["filing_id"]),
        client=_escaped(row["client"]),
        registrant=_escaped(row["registrant"]),
        filing_period=_escaped(row["filing_period"]),
        amount="$" + format(int(row["amount_usd"]), ","),
        specific_issues=_escaped(row["specific_issues"]),
        commitment=_render_commitment(sections, row),
        followup=_render_followup(sections, row),
        trace=_fill(
            sections["trace"],
            trace_url=_escaped(trace_links.build_row_trace_url(TRACED_INPUT, ordinal)),
        ),
    )


def _render_commitment(sections, row):
    said = _present(row["public_commitment"])
    if said is None:
        return sections["no_commitment"]
    return _fill(
        sections["commitment"],
        public_commitment=_escaped(said),
        commitment_source=_escaped(_present(row["commitment_source"]) or NO_SOURCE),
    )


def _render_followup(sections, row):
    # A flag is not an argument: a flagged row shows both texts it was decided from.
    judgment = _fill(
        sections["judgment"],
        alignment=_escaped(_present(row["alignment"]) or NOT_JUDGED),
    )
    if not bool(row["contradicts_commitment"]):
        return judgment
    said = _present(row["public_commitment"])
    if said is None:
        raise StepRefused(
            f"filing {row['filing_id']} is flagged as contradicting a public "
            f"commitment, yet the join matched none onto it, so this report cannot "
            f"say what it contradicts"
        )
    return judgment + _fill(
        sections["contradiction"],
        said=_escaped(said),
        lobbied_for=_escaped(row["specific_issues"]),
    )


def _fill(template, **values):
    filled = template
    for name, value in values.items():
        filled = filled.replace(TOKEN_OPEN + name + "]]", value)
    if TOKEN_OPEN in filled:
        raise ValueError(
            "the report markup has a placeholder this step does not fill"
        )
    return filled


def _escaped(value):
    return _html.escape(str(value))


def _present(value):
    if value is None or bool(pd.isna(value)):
        return None
    return str(value)
